809	\subsubsection{Close strategies have close game values}
810	
811	In this section, we will show that two strategies which are close in state-dependent distance are also close in value for any game~$\game$.
812	We note crucially that one of the two strategies must be \emph{projective} to apply this fact.
813	
814	\begin{fact}\label{fact:approx-delta-generalized-game-value}
815	Let $\calD$ be a distribution on questions~$x$, and for each~$x$ let $\mathrm{acc}(x)$ be a set of ``accepting" answers.
816	Given a state~$\psi$ and a strategy $\{A^x_a\}$ define
817	\begin{equation*}
818	\mathrm{val}(A) = \E_{\bx \sim \calD} \sum_{a \in \mathrm{acc}(x)} \bra{\psi} A^{\bx}_a \ket{\psi}.
819	\end{equation*}
820	Suppose $\{A^x_a\}$ and $\{B^x_a\}$ are two strategies such that $A^x_a \approx_\delta B^x_a$ on state~$\psi$ and distribution~$\calD$.
821	Suppose further that either~$A$ or~$B$ is a projective measurement (and the other is a POVM measurement).
822	Then
823	\begin{equation*}
824	\mathrm{val}(A) - O(\delta^{1/2}) \leq \mathrm{val}(B) \leq \mathrm{val}(A) + O(\delta^{1/2}).
825	\end{equation*}
826	\end{fact}
827	\begin{proof}
828	Assume without loss of generality that~$A$ is a projective measurement and~$B$ is a POVM measurement.
829	We will prove the fact by showing the following stronger statement:
830	for each~$x$, let~$S(x)$ be any set of answers~$a$,
831	and define
832	\begin{equation*}
833	\mathrm{val}(A,S) := \E_\bx \sum_{a \in S(x)} \bra{\psi} A^{\bx}_a\ket{\psi}.
834	\end{equation*}
835	Then $\mathrm{val}(A,S) \leq \mathrm{val}(B,S) + O(\delta^{1/2})$.
836	By taking $S(x) := \mathrm{acc}(x)$ this implies the lower bound $\mathrm{val}(A) - O(\delta^{1/2}) \leq \mathrm{val}(B)$,
837	and by taking $S(x) := \mathrm{rej}(x)$, defined to be the set of answers \emph{not} in $\mathrm{acc}(x)$,
838	then this implies the upper bound $\mathrm{val}(B) \leq \mathrm{val}(A) + O(\delta^{1/2})$.
839	
840	If we write $\ket{u_a^x} = A_{a}^{x}  \ket{\psi}$
841		and $\ket{w_a^x} = (B_{a}^{x} - A_{a}^{x}) \ket{\psi}$, then
842	\begin{equation*}
843	\Vert B_{a}^{x} \ket{\psi} \Vert^2
844	= \Vert \ket{u_a^x} + \ket{v_a^x} \Vert^2
845	 = \Vert\ket{u_a^x}\Vert^2 + \Vert\ket{w_a^x}\Vert^2
846	 + \braket{u_a^x \mid w_a^x} + \braket{w_a^x \mid u_a^x}.
847	\end{equation*}
848	By definition,
849	\begin{align*}
850	\mathrm{val}(B)
851	& = \E_{\bx} \sum_{a\in S(\bx)} \bra{\psi} B_{a}^{\bx} \ket{\psi}\\
852	& \geq \E_{\bx} \sum_{a\in S(\bx)} \bra{\psi} (B_{a}^{\bx})^2 \ket{\psi}\tag{because~$B$ is a POVM}\\
853	& = \E_{\bx} \sum_{a\in S(\bx)}\Vert B_{a}^{\bx} \ket{\psi} \Vert^2\\
854	& = \E_{\bx} \sum_{a\in S(\bx)} \Vert\ket{u_a^{\bx}}\Vert^2 + \Vert\ket{w_a^{\bx}}\Vert^2
855			 + \braket{u_a^{\bx} \mid w_a^{\bx}} + \braket{w_a^{\bx} \mid u_a^{\bx}}.
856	\end{align*}
857	Averaging over questions and summing over answers, the first term is exactly $\mathrm{val}(A)$ because~$A$ is projective.
858	The second term is always nonnegative, so we lower bound it by zero.
859	As for the last two terms,
860	\begin{equation}\label{eq:our-powers-combined--wind!}
861	\braket{u_a^x \mid w_a^x} + \braket{w_a^x \mid u_a^x}
862	\geq - 2 \cdot |\braket{u_a^x \mid w_a^x}| 
863	\geq -2 \cdot \Vert u_a^x \Vert \cdot \Vert w_a^x \Vert.
864	\end{equation}
865	Applying Cauchy-Schwarz,
866	Jensen's inequality,
867	and \Cref{fact:measurement-sub-measurement-switcheroo},
868	\begin{equation}\label{eq:our-powers-combined--heart!}
869	\E_{\bx} \sum_{a \in S(\bx)} \Vert u_a^{\bx} \Vert \cdot \Vert w_a^{\bx} \Vert
870	\leq \E_{\bx} \sqrt{\sum_{a \in S(\bx)} \Vert u_a^{\bx} \Vert^2 \cdot  \sum_{a \in S(\bx)}\Vert w_a^{\bx}\Vert^2 }
871	\leq \sqrt{\E_{\bx} \sum_{a \in S(\bx)}\Vert w_a^{\bx}\Vert^2 }.
872	\end{equation}
873	But the expectation inside the root is at most $O(\delta)$ because $A^{x}_a \approx_{\delta} B^{x}_a$.
874	Combining \Cref{eq:our-powers-combined--wind!,eq:our-powers-combined--heart!} completes the proof.
875	\end{proof}
876	
877	We will typically, though not always,
878	apply \Cref{fact:approx-delta-generalized-game-value} in the following special case.
879	
880	\begin{fact}\label{fact:approx-delta-game-value}
881	Let $\game$ be a game whose questions $(\bx_1, \bx_2) \sim \game$ have marginal distribution $\bx_1 \sim \calD$.
882	Suppose $\{A_a^x\}$
883	and $\{B_a^x\}$ are measurements such that
884	$
885	A_a^x  \otimes I \approx_\delta B_a^x \otimes I
886	$
887	on state $\psi$ and distribution~$\calD$.
888	Consider the strategies $\calS_A = \{\psi, A\}$ and $\calS_B = \{\psi, B\}$.
889	If either~$A$ or~$B$ is a projective measurement (and the other is a POVM measurement), then
890	\begin{equation*}
891	\valstrat{\game}{\calS_A} - O(\delta^{1/2}) \leq \valstrat{\game}{\calS_B} \leq \valstrat{\game}{\calS_A} + O(\delta^{1/2}).
892	\end{equation*}
893	\end{fact}
894	\begin{proof}
895	First, we observe that
896	\begin{equation*}
897	A^{x_1}_{a_1} \otimes A^{x_2}_{a_2}
898	\approx_{\delta} A^{x_1}_{a_1} \otimes B^{x_2}_{a_2}
899	\approx_{\delta} B^{x_1}_{a_1} \otimes B^{x_2}_{a_2}
900	\end{equation*}
901	by \Cref{fact:add-a-proj}.
902	The result follows by applying \Cref{fact:approx-delta-game-value} with
903	``$A$" set to $A^{x_1}_{a_1} \otimes A^{x_2}_{a_2}$,
904	``$B$" set to $B^{x_1}_{a_1} \otimes B^{x_2}_{a_2}$,
905	and ``$\calD$" set to the distribution on $(\bx_1, \bx_2)$.
906	We note that ``$\mathrm{val}(A)$" there is equal to $\valstrat{\game}{\calS_A}$ here and
907	``$\mathrm{val}(B)$" there is equal to $\valstrat{\game}{\calS_B}$ here.
908	\end{proof}
909	
910	\subsubsection{Generating new measurements}
911	
912	In this section, we show how to combine multiple measurements into a single measurement by ``sandwiching" them together.
913	
914	\begin{fact}\label{fact:sandwich}
915	Let $k \geq 0$ be a constant.
916	Let $\{A^x_{a_1, \ldots, a_k}\}$ be a projective measurement.
917	For each $1 \leq i \leq k$, let $\{(B_i)^x_{a_i}\}$ be a projective measurement, and suppose that
918	\begin{equation}\label{eq:no-take-only-throw}
919	(A^x_{a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta} I_{\reg{Alice}} \otimes ((B_i)^x_{a_i})_{\reg{Bob}}.
920	\end{equation}
921	Define the POVM measurement $\{J^x_{g_1, \ldots, g_k}\}$ as
922	\begin{equation*}
923	J^x_{a_1, \ldots, a_k} := (B_k)^x_{a_k} \cdots (B_2)^x_{a_2} \cdot (B_1)^x_{a_1} \cdot (B_2)^x_{a_2} \cdots (B_k)^x_{a_k}.
924	\end{equation*}
925	Then
926	\begin{equation*}
927	(A^x_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta^{1/2}} I_{\reg{Alice}} \otimes (J^x_{a_1, \ldots, a_k})_{\reg{Bob}}.
928	\end{equation*}
929	\end{fact}
930	\begin{proof}

 930	\begin{proof}
 931	For each $1 \leq i \leq k$, 
 932	\Cref{eq:no-take-only-throw} implies that
 933	\begin{equation*}
 934	(A^x_{a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \approx_{\delta} I_{\reg{Alice}} \otimes ((B_i)^x_{a_i})_{\reg{Bob}}.
 935	\end{equation*}
 936	Now, we repeatedly apply this using \Cref{fact:add-a-proj}:
 937	\begin{align*}
 938	(A^x_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}}
 939	& = (A^x_{a_k} \cdots A^x_{a_2} \cdot A^x_{a_1} \cdot A^x_{a_2} \cdots A^x_{a_{k}})_{\reg{Alice}} \otimes I_{\reg{Bob}}\\
 940	& \approx_{\delta} (A^x_{a_k} \cdots A^x_{a_2} \cdot A^x_{a_1} \cdot A^x_{a_2} \cdots A^x_{a_{k-1}})_{\reg{Alice}} \otimes ((B_k)^x_{a_k})_{\reg{Bob}}\\
 941	&\qquad\qquad\qquad \qquad \qquad \qquad \cdots\\
 942	& \approx_{\delta} I_{\reg{Alice}} \otimes ((B_k)^x_{a_k} \cdots (B_2)^x_{a_2} \cdot (B_1)^x_{a_1} \cdot (B_2)^x_{a_2} \cdots (B_k)^x_{a_k})_{\reg{Bob}}\\
 943	& = I_{\reg{Alice}} \otimes (J^x_{a_1, \ldots, a_k})_{\reg{Bob}}.
 944	\end{align*}
 945	The fact now follows from \Cref{fact:almost-agreement} and the fact that~$A$ is a projective measurement.
 946	\end{proof}
 947	
 948	Next, we extend \Cref{fact:sandwich} to the case of polynomial measurements (see \Cref{sec:classical-q-low-deg} below).
 949	These are structured measurements in which the prover returns the evaluation of a function sampled independently from their input.
 950	The goal is to retain this structure even after ``sandwiching" them together.
 951	
 952	\begin{fact}\label{fact:low-degree-sandwich}
 953	Let $k \geq 0$ be a constant.
 954	Let $\calD$ be a distribution on questions $x \in \calX$.
 955	For each $1 \leq i \leq k$, let $\calG_i$ be a set of functions $g_i : \calX \rightarrow \calR_i$.
 956	and let $\{G^i_g\}$ be a projective measurement with outcomes from this set.
 957	Suppose that the set $\calG_i$ has the following distance property:
 958	for any two nonequal $g_i, g_i' \in \calG_i$, the probability that $g_i(\bx) = g_i'(\bx)$, over a random $\bx \sim \calD$, is at most $\eps$.
 959	
 960	Let $\{A_{g_1, \ldots, g_k}\}$ be a projective measurement with outcomes $g_i \in \calF_i$.
 961	For each $1 \leq i \leq k$, suppose that
 962	\begin{equation}\label{eq:treat-yo-self}
 963	(A_{[g_i(x) = a_i]})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta} I_{\reg{Alice}} \otimes (G^i_{[g_i(x)=a_i]})_{\reg{Bob}}.
 964	\end{equation}
 965	Define the POVM measurement $\{J_{g_1, \ldots, g_k}\}$ as
 966	\begin{equation*}
 967	J_{g_1, \ldots, g_k} := G^k_{g_k} \cdots G^2_{g_2} \cdot G^1_{g_1} \cdot G^2_{g_2} \cdots G^k_{g_k}.
 968	\end{equation*}
 969	Then
 970	\begin{equation*}
 971	(A_{[g_1(x), \ldots, g_k(x) = a_1, \ldots, a_k]})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{(\delta+\eps)^{1/2}} I_{\reg{Alice}} \otimes (J_{[g_1(x), \ldots, g_k(x) = a_1, \ldots, a_k]})_{\reg{Bob}}.
 972	\end{equation*}
 973	\end{fact}
 974	\begin{proof}
 975	Let $1 \leq i \leq k$.
 976	By~\Cref{eq:treat-yo-self},
 977	if Alice measures with~$A$, producing~$\bg_i$, and Bob measures with~$G^i$, producing~$\bg_i'$,
 978	then the probability that $\bg_i(\bx) \neq \bg_i'(\bx)$ is $O(\delta)$.
 979	Write $\eta$ for the probability that $\bg_i \neq \bg_i'$.
 980	Then we have the expression $\eta \cdot (1-\eps) \leq O(\delta)$ or, equivalently, $\eta \leq O(\delta/(1-\eps))$.
 981	When $\eps < 1/2$, this gives the bound $\eta \leq O(\delta)$, and when $\eps \geq 1/2$, we have the trivial bound $\eta \leq O(\eps)$.
 982	As a result, $\eta = O(\delta + \eps)$.
 983	
 984	In conclusion,
 985	\begin{equation*}
 986	(A_{g_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta + \eps} I_{\reg{Alice}} \otimes (G^i_{g_i})_{\reg{Bob}}.
 987	\end{equation*}
 988	We can now apply \Cref{fact:sandwich} to $A_{g_1, \ldots, g_k}$ and the $G^i_{g_i}$ measurements.
 989	It implies that
 990	\begin{equation*}
 991	(A_{g_1, \ldots, g_k})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{(\delta+\eps)^{1/2}} I_{\reg{Alice}} \otimes (J_{g_1, \ldots, g_k})_{\reg{Bob}}.
 992	\end{equation*}
 993	The fact now follows from the data processing inequality \Cref{fact:specialize-the-simeq}.
 994	\end{proof}
 995	
 996	In our next fact, we show that \Cref{fact:low-degree-sandwich} holds even when we drop the structured assumption on the~$A$ matrix.
 997	The tradeoff is that we must now assume that the~$k$ different measurements act on different parts of the input string.
 998	In this case, the distance condition becomes slightly more cumbersome to state.
 999	
1000	\begin{fact}\label{fact:low-degree-sandwich-on-steroids}
1001	Let $k \geq 0$ be a constant.
1002	Let $\calD$ be a distribution on questions $(x, y_1, \ldots, y_k)$, where each $y_i \in \calY_i$.
1003	For each $1 \leq i \leq k$, let $\calG_i$ be a set of functions $g_i : \calY_i \rightarrow \calR_i$.
1004	and let $\{(G_i)^x_g\}$ be a projective measurement with outcomes from this set.
1005	(For the $i=1$ case, we also allow this measurement to be a POVM.)
1006	Suppose that the set $\calG_i$ has the following distance property:
1007	fix a question $z = (x, y_1, \ldots, y_{i-1}, y_{i+1}, \ldots, y_k)$, and let $\calD_z$ be the distribution on~$y_i$ conditioned on the other outcomes~$z$.
1008	Then for any two nonequal $g_i, g_i' \in \calG_i$, the probability that $g_i(\by_i) = g_i'(\by_i)$, over a random $\by_i \sim \calD_z$, is at most $\eps$.
1009	
1010	Let $\{A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k} \}$ be a projective measurement with outcomes $g_i \in \calF_i$.
1011	For each $1 \leq i \leq k$, suppose that
1012	\begin{equation}\label{eq:gonna-compare-like-a-pear}
1013	(A^{x, y_1, \ldots, y_k}_{a_i})_{\reg{Alice}} \otimes I_{\reg{Bob}} \simeq_{\delta} I_{\reg{Alice}} \otimes ((G_i)^x_{[g_i(y_i)=a_i]})_{\reg{Bob}}.
1014	\end{equation}
1015	Suppose also that
1016	\begin{equation}\label{eq:spend-some-time-reflecting}
1017	(A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}}
1018		\simeq_{\delta} I_{\reg{Alice}} \otimes (A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k})_{\reg{Bob}}.
1019	\end{equation}
1020	Define the POVM measurement $\{J^x_{g_1, \ldots, g_k}\}$ as
1021	\begin{equation*}
1022	J^x_{g_1, \ldots, g_k} := (G_k)^x_{g_k} \cdots (G_2)^x_{g_2} \cdot (G_1)^x_{g_1} \cdot (G_2)^x_{g_2} \cdots (G_k)^x_{g_k}.
1023	\end{equation*}
1024	Then
1025	\begin{equation*}
1026	(A^{x, y_1, \ldots, y_k}_{a_1, \ldots, a_k})_{\reg{Alice}} \otimes I_{\reg{Bob}}
1027		\simeq_{\poly(\delta, \eps)} I_{\reg{Alice}} \otimes (J^x_{[g_1(y_1), \ldots, g_k(y_k) = a_1, \ldots, a_k]})_{\reg{Bob}}.
1028	\end{equation*}
1029	\end{fact}
1030	\begin{proof}
1031	First, we show how to reduce this to the $k = 2$ case. Then we prove it for that case.
1032	Assume the fact holds when $k = 2$.  Define the POVM measurement $\{(J_i)^x_{g_1, \ldots, g_i}\}$ as
1033	\begin{equation*}
